import React, { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';

const PlasmaDonationTracker = () => {
  const [donationCount, setDonationCount] = useState(0);
  const [financialGoal, setFinancialGoal] = useState(0);
  const [goalInput, setGoalInput] = useState('');
  const [timer, setTimer] = useState(0);
  const [isTiming, setIsTiming] = useState(false);

  useEffect(() => {
    let interval;
    if (isTiming) {
      interval = setInterval(() => {
        setTimer((prev) => prev + 1);
      }, 1000);
    } else if (!isTiming && timer !== 0) {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isTiming, timer]);

  const handleDonation = () => {
    setDonationCount((prev) => prev + 1);
    setIsTiming(true);
    window.open('https://www.surveylink.com', '_blank');
  };

  const handleSetGoal = () => {
    setFinancialGoal(parseInt(goalInput) || 0);
  };

  const peopleHelped = donationCount * 3;
  const totalEarnings = donationCount * 50;
  const progress = financialGoal ? (totalEarnings / financialGoal) * 100 : 0;

  return (
    <div className="p-6">
      <Card className="mb-4">
        <CardContent>
          <h2 className="text-xl mb-2">Set Your Financial Goal for Plasma Donation</h2>
          <input
            type="number"
            className="p-2 border rounded mb-2 w-full"
            placeholder="Enter your financial goal"
            value={goalInput}
            onChange={(e) => setGoalInput(e.target.value)}
          />
          <Button onClick={handleSetGoal}>Set Goal</Button>
        </CardContent>
      </Card>
      <Card className="mb-4">
        <CardContent>
          <h2 className="text-xl mb-2">Donated Plasma Tracker</h2>
          <Button onClick={handleDonation} className="mb-2">
            Donated Plasma!
          </Button>
          <p className="mb-2">People Helped: {peopleHelped}</p>
          <p className="mb-2">Total Earnings: ${totalEarnings}</p>
          <p className="mb-2">Financial Goal: ${financialGoal}</p>
          <Progress value={progress} className="mb-2" />
          <p className="mb-2">Timer: {timer} seconds</p>
        </CardContent>
      </Card>
    </div>
  );
};

export default PlasmaDonationTracker;
